const minNumSide = 4;
const PENS = ["darkcyan", "red", "darkorange", "orange", "yellow"].reverse();

function setup() {
	createCanvas(windowWidth, windowHeight);
	frameRate(30);
	noStroke();
	// // noLoop() removed for animation
}

function draw() {
	blendMode(BLEND);
	background(212);
	blendMode(MULTIPLY);

	push();
	const S = max(width, height);
	let cx = width/2;
	let cy = height/2;
	if ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) > 0 && (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) < width) cx = map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, 0.45, 0.55) * width;
	if ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) > 0 && (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) < height) cy = map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, 0.45, 0.55) * height;
	// translate(cx, cy);

	let szeS = max(width, height) / (2 * minNumSide);
	let nx = ~~(width / szeS / 2);
	let ny = ~~(height / szeS / 2);
	szeS *= 0.95;
	// console.log(nx, ny);

	let szeD = szeS * 0.05;
	let sze = szeS - szeD * PENS.length;

	for (let p = 0; p < PENS.length; p++) {
		fill(0);
		sze += szeD;
		let szeO = sze; //  * 1.05;
		push();
		let ff = p/PENS.length;
		let tx = lerp(cx, width/2, ff);
		let ty = lerp(cy, height/2, ff);
		translate(tx, ty);
		beginClip({ invert: true });
		for (let j = 0; j < ny; j++) {	
			for (let i = 0; i < nx; i++) {
				const x = sze/2 + i * sze;
				const y = sze/2 + j * sze;
				circle(x, y, szeO);
				circle(-x, y, szeO);
				circle(x, -y, szeO);
				circle(-x, -y, szeO);
			}
		}
		endClip();
		fill(PENS[p]);
		rect(-sze/2-(nx-1)*sze, -(sze/2+(ny-1)*sze), 2*nx*sze-sze, 2*ny*sze-sze);
		pop();
	}

	pop();
}

function windowResized() {
	resizeCanvas(windowWidth, windowHeight);
	redraw();
}
